S=/private/tmp/claude-501/-Users-kentgang-git3-katalyst/3bcc9024-06ad-4692-9a6a-e303e34756e0/scratchpad; W=/Users/kentgang/git3/katalyst-wt/feat-03b-wires
cd $W/backend && (env -u ANTHROPIC_API_KEY -u FRED_API_KEY nohup uv run uvicorn katalyst.api.main:app --port 8014 > $S/coord-v-backend.log 2>&1 &)
cd $W/frontend && (KATALYST_API_URL=http://localhost:8014 nohup npm run dev -- --port 5186 --strictPort > $S/coord-v-vite.log 2>&1 &)
for i in $(seq 1 30); do curl -sf http://localhost:5186/api/healthz >/dev/null 2>&1 && break; sleep 1; done
cat > $S/coord-v.mjs <<'EOF'
import { chromium } from "playwright";
const out = process.argv[2];
const b = await chromium.launch();
const p = await b.newPage({ viewport: { width: 1600, height: 1000 }, deviceScaleFactor: 1 });
const errors = []; p.on("pageerror", e => errors.push(String(e))); p.on("console", m => { if (m.type() === "error") errors.push(m.text()); });
await p.goto("http://localhost:5186/"); await p.waitForTimeout(600);
await p.getByText("Open the map").click(); await p.waitForTimeout(2500);
const tiles = await p.locator(".react-flow__node").count();
const wires = await p.locator(".react-flow__edge").count();
await p.locator(".react-flow__node").nth(3).click({ position: { x: 20, y: 10 } }); await p.waitForTimeout(500);
await p.screenshot({ path: `${out}/coord-v-01-claim-selected.png` });
const panel = await p.evaluate(() => document.body.innerText.includes("Nothing selected"));
const dialogs = await p.evaluate(() => document.querySelectorAll("[role=dialog],dialog,[aria-modal]").length);
const outside = await p.evaluate(() => performance.getEntriesByType("resource").map(r => r.name).filter(n => !n.startsWith(location.origin)));
console.log(JSON.stringify({ tiles, wires, stillNothingSelected: panel, dialogs, outsideRequests: outside, errors }));
await b.close();
EOF
cd $S && node coord-v.mjs $S/v-shots 2>&1 | tail -2; pkill -f "uvicorn katalyst.api.main:app --port 8014"; pkill -f "vite.*5186"

